-- Rifts World Book 34: Northern Gun Two, three aircraft (printed 194-200): Dragonfly, Skybunker, Sky Wolf
-- 3 vehicle rows, with 31 locations and 9 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~321-northern-gun-2-jet-packs-aircraft.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('ng-hc1000-dragonfly', 'NG-HC1000 Dragonfly Hover-Chopper', 'rifts', 'vehicle', 'Two: pilot and gunner.', 'One human-sized passenger (or equipment) can be crammed into the cockpit with no seat; the pilot is then -10% to piloting.', 'Not possible.', 'Maximum 200 mph (320 km); hovers and has VTOL. Ceiling 8,000 ft (2,438 m); air-to-ground attacks only from 4,000 ft (1,219 m) or lower.', NULL, 'Height 9 ft (2.7 m), low profile; wingspan 28 ft (8.5 m); length 36 ft (11 m)', '4 tons; 5 tons with every missile and the rail gun drum loaded', 195, 1, NULL, 2300000, '2.8 million credits nuclear, 2.3 million Solid Oxide; the lowest is stored. Missiles are extra. Not sold on NG''s open market, only to chosen kingdoms and armies (fair to poor availability); a stolen or captured one goes for two to three times list on the Black Market or from pirates.', 'Model NG-HC1000 (Class: Hover Combat Gunship). Designed by a team led by Joshua Hill, Douglas Rood and David Dunham, it crosses a rocket cycle with an old-style attack helicopter: hover jets give it VTOL, hovering and low, slow-to-moderate flight, and it handles well in cities and wilderness alike. It is a weapons platform built to kill tanks, giant robots, monsters and dragons, not a scout or medevac craft; it excels at pop-up strikes from behind a ridge or a building where there is cover, rivalling the CS Black Lightning there, but in open battle it is slow, a little ungainly and easy prey for nimble power armor, faster aircraft and dug-in guns. Popular around the Great Lakes and the Saint Lawrence; the Army of Ishpeming has flown it for seven years as a tank and robot buster and troop support, it has been sold quietly to reputable forces for three, and the Tundra Rangers and Free Quebec have bought some. Navies use it for coastal patrol, anti-submarine work and hunting pirates and sea serpents, and big warships carry a wing on deck. Range: years on its nuclear supply, but the hover jets need two hours to cool after 12 hours of use. Power: nuclear (about 15 years) or Solid Oxide. Cargo: a locker in the cockpit for two rifles, three pistols, a portable radio, a week of rations, an NG-S2 survival kit and two gallons (7.6 liters) of water. Wing stores: while any wing rack or wing launcher still holds a missile, speed drops 10% and dogfighting, evasive and trick manoeuvres are -10% piloting (each), lifted once they are empty. Sensors and features roughly match robot vehicles''.', 'Rifts World Book 34: Northern Gun Two p.194-196'),
  ('ng-hc2000-skybunker', 'NG-HC2000 Skybunker Hover Carrier', 'rifts', 'vehicle', 'Four: pilot, co-pilot, communications and sensor operator, gunner.', '30 fully equipped troops in M.D.C. body armor, with room besides for 18 paratroopers or nine troops in flying power armor (Blue Hawk, Red Hawk, Ironwing, Samson and the like); or supplies; or 12-18 troops with 4-8 small vehicles such as hovercycles, rocket bikes and jeeps.', 'Not possible, though it can skim the ground at full flying speed.', 'Maximum 280 mph (448 km); cruises at 50-80 mph (80 to 128 km). Hovers and has VTOL. Ceiling about 4,000 ft (1,219 m). With cargo strapped outside or troops riding on top, 40 mph (64 km) at most.', NULL, 'Height 17 ft (5.2 m); wingspan 23 ft (7 m); length 44 ft (13.4 m)', '34 tons', 410, 1, NULL, 24000000, '28.5 million credits nuclear, 24 million Solid Oxide; the lowest is stored. No electric battery version.', 'Model NG-HC2000 (Class: Armored Hover Personnel Carrier). A flying APC modelled on the Coalition''s Death Bringer and SkyLifter: a big hover drive lets it cross forest, hills, water and man-made obstacles, pairing a tank''s plating with an aircraft''s reach, half helicopter and half infantry fighting vehicle. Long in Ishpeming''s service, it is now on general sale because demand is high, and kingdoms and large mercenary companies are buying. It moves troops, cargo and vehicles, drops rapid reaction forces, and can be fitted out as a field base or a mobile hospital. Cargo: up to 10 tons inside, usually soldiers with their packs and arms or crates of supplies; up to 6 more tons can be lashed outside and troops can ride on the roof, but above 40 mph (64 km) riders are thrown off and lashed cargo has a 01-30% chance per 15 minutes of tearing loose. Range unlimited on nuclear (about 12 years) or Solid Oxide, but the hover jets need cooling after 6-8 hours of use. Door gunners: harnesses at both side doors and three at the rear door let an armored or power-armored soldier clip in and shoot out with any handheld weapon. Its troops are a weapon too: infantry are put down at a landing zone, while riders of rocket bikes or hovercycles and wearers of flying power armor can leave in mid-flight. Sensors and features roughly match robot vehicles''.', 'Rifts World Book 34: Northern Gun Two p.196-197'),
  ('ng-h500-sky-wolf', 'NG-H500 Sky Wolf Combat Helicopter', 'rifts', 'vehicle', 'Two: pilot and gunner.', '4-8 by size and armor: four in man-sized power armor, six in EBA or eight unarmored civilians.', 'Not possible.', 'Maximum 150 mph (240 km); cruises at 100 mph (160 km). Hovers and has VTOL. Ceiling 10,000 ft (3,048 m); air-to-ground attacks only from 4,000 ft (1,219 m) or lower.', NULL, 'Height 9 ft (2.7 m), low profile; body 12 ft (3.7 m) wide, rotor diameter 40 ft (12.2 m); length 48 ft (14.6 m)', '2 tons', 145, 1, NULL, 425000, '1.4 million credits nuclear, 790,000 Solid Oxide, 425,000 electric battery; the lowest is stored. Missiles are extra. Fair to good availability, best at Ishpeming and MercTown.', 'Model NG-H500 (Class: Combat and Reconnaissance Helicopter). Designed under Michael Johnson, D.R. Boudreaux and Christopher Murray: an ordinary rotor gunship meant for supporting, inserting and pulling out troops, for rescues, and for military and police patrols. Power armor with jump jets (Aurora Blaze, Cougar, Lynx, Mantis) can leap from it while it hovers a hundred or a few hundred feet up, and troops wearing jet packs can step out at any height while it hovers or flies under 30 mph (48 km); it usually carries 4-6 combat troops for a ground or air assault. Mercenaries, armies, police, explorers, couriers, Black Marketeers and border patrols like it, and navies fly it off medium and large ships, but it works best in cities with troops around it and is exposed alone in the wilds. Range: unlimited on nuclear (about 15 years) or Solid Oxide, 600 miles (960 km) per charge on electric; the rotor needs two hours'' rest after 36 hours of continuous use. Cargo: a cockpit locker for two rifles, three pistols, a portable radio, a week of rations, an NG-S2 survival kit and two gallons (7.6 liters) of water. The opening paragraph gives it 12 mini-missiles; the weapon entry prints 24 (12 per launcher), stored here. Sensors and features roughly match robot vehicles''.', 'Rifts World Book 34: Northern Gun Two p.198-200');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('ng-hc1000-dragonfly', 'Main Jet Thrusters (2, rear)', 80, 'Each.', 1),
  ('ng-hc1000-dragonfly', 'Hover Jets (3, undercarriage)', 20, 'Each. Small target: Called Shot, -4 to strike.', 2),
  ('ng-hc1000-dragonfly', 'Spotlight (2, top of cockpit)', 5, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-hc1000-dragonfly', 'Ion Pulse Turret (1, top turret)', 35, 'Small target: Called Shot, -4 to strike.', 4),
  ('ng-hc1000-dragonfly', 'Dual Rail Gun (1, nose)', 50, 'Small target: Called Shot, -4 to strike.', 5),
  ('ng-hc1000-dragonfly', 'Mini-Missile Box Launchers (24, side)', 15, 'Each. Small target: Called Shot, -4 to strike.', 6),
  ('ng-hc1000-dragonfly', 'Wing Mini-Missile Launchers (2, per wing)', 50, 'Each. Small target: Called Shot, -4 to strike. The weapon list puts one 12-shot launcher on each wing.', 7),
  ('ng-hc1000-dragonfly', 'Wing Launch Racks (2, each holds 4 missiles)', 20, 'Each. Small target: Called Shot, -4 to strike.', 8),
  ('ng-hc1000-dragonfly', 'Wings (2)', 70, 'Each. It keeps flying on its hover jets: one wing lost cuts speed and altitude 30% and piloting -20%; losing both wings, or a wing and the tail, a further 30% and -20% (60% and -40% in all). A depleted wing drops whatever weapons and missiles it still carries, which detonate before landing on 01-80%.', 9),
  ('ng-hc1000-dragonfly', 'Tail Section', 120, 'Small target: Called Shot, -4 to strike. Destroyed: -20% piloting and 30% off speed and altitude; cumulative with wing losses.', 10),
  ('ng-hc1000-dragonfly', 'Reinforced Pilot Compartment', 50, 'Small target: Called Shot, -4 to strike.', 11),
  ('ng-hc1000-dragonfly', 'Main Body', 195, 'Depleted, the craft falls; a piloting roll at -20% crash-lands it so the crew and any passenger walk away from the wreck inside the broken cockpit.', 12),
  ('ng-hc2000-skybunker', 'Main Jet Thrusters (4; rear)', 90, 'Each.', 1),
  ('ng-hc2000-skybunker', 'Hover Jets (10; undercarriage)', 15, 'Each. Small target: Called Shot, -4 to strike.', 2),
  ('ng-hc2000-skybunker', 'Laser Turrets (3)', 65, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-hc2000-skybunker', 'Main Cargo Door (1; rear)', 110, NULL, 4),
  ('ng-hc2000-skybunker', 'Extendable Cargo Ramp (1; rear)', 80, NULL, 5),
  ('ng-hc2000-skybunker', 'Side Cabin Doors (2)', 80, 'Each.', 6),
  ('ng-hc2000-skybunker', 'Searchlight (1; mounted on top; optional)', 30, 'Small target: Called Shot, -4 to strike.', 7),
  ('ng-hc2000-skybunker', 'Headlights (4)', 10, 'Each. Small target: Called Shot, -4 to strike.', 8),
  ('ng-hc2000-skybunker', 'Other Lights (4; top and bottom)', 5, 'Each. Small target: Called Shot, -4 to strike.', 9),
  ('ng-hc2000-skybunker', 'Window Slit (1; forward)', 22, 'Small target: Called Shot, -4 to strike.', 10),
  ('ng-hc2000-skybunker', 'Reinforced Crew Compartment', 120, NULL, 11),
  ('ng-hc2000-skybunker', 'Main Body', 410, 'Depleted, the craft falls; a piloting roll at -45% crash-lands it so the crew are unhurt inside the wrecked compartment, and troops or cargo aboard take only 1D4x10 M.D. each (3D4x10+30 M.D. each in an uncontrolled crash).', 12),
  ('ng-h500-sky-wolf', 'Helicopter Main Rotor (1, top)', 100, 'Small target: Called Shot, -4 to strike. Destroyed, the craft falls; a piloting roll at -25% crash-lands it with no one aboard hurt.', 1),
  ('ng-h500-sky-wolf', 'Tail Section', 100, 'Destroyed, the craft falls; a piloting roll at -25% crash-lands it with no one aboard hurt.', 2),
  ('ng-h500-sky-wolf', 'Nose Gun', 50, 'Small target: Called Shot, -4 to strike.', 3),
  ('ng-h500-sky-wolf', 'Mini-Missile Box Launchers (2, one per side)', 20, 'Each. Small target: Called Shot, -4 to strike.', 4),
  ('ng-h500-sky-wolf', 'Landing Struts (2)', 40, 'Each. Small target: Called Shot, -4 to strike.', 5),
  ('ng-h500-sky-wolf', 'Reinforced Pilot Compartment', 50, 'Small target: Called Shot, -4 to strike.', 6),
  ('ng-h500-sky-wolf', 'Main Body', 145, 'Depleted, the craft falls; a piloting roll at -20% crash-lands it with no one aboard hurt, though the helicopter is wrecked.', 7);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-hc1000-dragonfly', 1, 'NG-D1000 Dual Rail Gun Nose Turret', '6D6 M.D. per single burst (30 rounds); 1D6x10 M.D. per simultaneous double burst from both barrels (60 rounds)', 1, '4,000 ft (1,219 m)', 'Each single or double burst is one melee attack', '3,000-round internal drum: 100 single or 50 double bursts. Reloading needs special equipment, a trained ground crew and 15-20 minutes', NULL, 'Standard. A twin-barrel turret built on the NG-404 heavy rail gun, slung under the nose; swings 90 degrees to either side and tilts 40 degrees up or down without moving the aircraft. Assault, strafing and anti-personnel; secondary defense.'),
  ('ng-hc1000-dragonfly', 2, 'Double-Barrel Ion Turret', '6D6 M.D. per dual blast', 1, '1,400 ft (426.7 m)', 'Each blast is one melee attack', 'Effectively unlimited', NULL, 'Standard. A low turret on top, behind and above the cockpit, worked by gunner or pilot; turns through 200 degrees with a 90 degree arc up and down. Defense against flyers that try to dogfight it or drop on it from above.'),
  ('ng-hc1000-dragonfly', 3, 'NG-D100 Mini-Missile Box Launchers (12 per side)', 'By mini-missile type; armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.) are standard', 1, 'About 1 mile (1.6 km)', 'One at a time or volleys of 2, 4, 6, 8, 12 or 24; each volley is one melee attack', '48 mini-missiles: two in each of the 24 box launchers', NULL, 'Standard. Two banks of 12 on the fuselage sides behind the cockpit. Anti-armor and anti-aircraft; secondary anti-fortification, assault and defense. Never loaded with mini-torpedoes.'),
  ('ng-hc1000-dragonfly', 4, 'Wing Missile Racks (2)', 'By missile type. Short-range: armor piercing or plasma (2D6x10 M.D.) standard. Medium-range: armor piercing (3D6x10 M.D., 20 ft/6.1 m radius) or medium high explosive (2D6x10 M.D., 30 ft/9.1 m radius) standard', 1, '5 miles (8 km) short-range; 40 miles (64 km) medium-range', 'One at a time or volleys of 2 or 4; each missile or volley is one melee attack, by pilot or gunner', '8 short-range (four per wing) or 4 medium-range (two per wing)', NULL, 'Standard. One rack hung on each wing. Anti-armor and anti-monster; secondary anti-aircraft and anti-fortification. While any rack is loaded: speed -10% and -10% piloting for dogfighting, evasion and tricks.'),
  ('ng-hc1000-dragonfly', 5, 'NG-D1212 Mini-Missile Wing Launchers (2)', 'By mini-missile type, smoke, Hex and explosive included; standard load is 6 smoke, 4 Hex or tear gas, 8 armor piercing (1D4x10 M.D.) and 8 plasma (1D6x10 M.D.)', 1, '1 mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6; each volley is one melee attack', '24 mini-missiles, 12 per wing launcher', NULL, 'Standard. A 12-shot box launcher on each wing; mini-torpedoes may replace the missiles. Anti-armor and anti-aircraft; secondary anti-fortification, assault and defense. While either is loaded: speed -10% and -10% piloting for dogfighting, evasion and tricks. The standard mix as printed sums to 26 against a payload of 24.'),
  ('ng-hc2000-skybunker', 1, 'Laser Turrets (3)', '4D6 M.D. per simultaneous dual blast', 1, '2,000 ft (610 m)', 'Each blast is one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Standard. Three twin-barrel turrets on the roof, two forward behind the cockpit and one aft; each turns 360 degrees with a 45 degree arc up and down. Worked by the gunner or co-pilot, or a passenger at need, chiefly against aircraft and flyers.'),
  ('ng-hc2000-skybunker', 2, 'Door Gunner positions', 'As the handheld weapon used', 0, NULL, NULL, NULL, NULL, 'A strap and harness at each side door and three at the rear cargo door, so an armored or power-armored soldier can open up and shoot any hand weapon (a laser rifle, a rail gun, a grenade launcher) at air or ground targets.'),
  ('ng-h500-sky-wolf', 1, 'NG-SW500 Dual Rail Gun Nose Turret', '4D6 M.D. per short burst (20 rounds); 1D4x10 M.D. per long burst (40 rounds)', 1, '4,000 ft (1,219 m)', 'Each burst is one melee attack', '3,200-round internal drum: 160 short or 80 long bursts. Reloading needs special equipment, a trained ground crew and 10-15 minutes', NULL, 'Standard. A gatling-style rail gun on an arm under the nose; swings 90 degrees to either side and tilts 45 degrees up or down without moving the helicopter. Assault, strafing and anti-personnel; secondary anti-flyer and defense. Option: a heavy long-range laser may replace it, with the same arcs and controls: 4D6 M.D. per blast, 4,000 ft (1,219 m), each blast one melee attack, effectively unlimited payload.'),
  ('ng-h500-sky-wolf', 2, 'NG-SW66 Mini-Missile Wing Launchers (2; side)', 'By mini-missile type; armor piercing (1D4x10 M.D.) and/or plasma (1D6x10 M.D.) are standard', 1, '1 mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6; each volley is one melee attack', '24 mini-missiles, 12 per launcher', NULL, 'Standard. A box launcher on each side behind the cockpit; mini-torpedoes may replace the missiles. Anti-armor and anti-aircraft; secondary anti-fortification, assault and defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-hc1000-dragonfly', 'ng-hc2000-skybunker', 'ng-h500-sky-wolf');
SELECT 'their 31 locations are in' AS assertion, count(*) AS got, 31 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-hc1000-dragonfly', 'ng-hc2000-skybunker', 'ng-h500-sky-wolf');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-hc1000-dragonfly', 'ng-hc2000-skybunker', 'ng-h500-sky-wolf');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-hc1000-dragonfly', 'ng-hc2000-skybunker', 'ng-h500-sky-wolf') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

